react-native-webview Here For react-native-webview's Android overscroll Always The platform's <code>android.webView.overScrollMode: 0</code> iOS inline video Off On <code>ios.configuration.allowsInlineMediaPlayback: false</code> iOS AirPlay Off On <code>ios.configuration.allowsAirPlayForMediaPlayback: false</code> iOS content insets <code>never</code>, indicators not adjusted <code>automatic</code>, indicators adjusted Two <code>ios.scrollView</code> keys, below iOS debugging (<code>webviewDebuggingEnabled</code>) Off On in <code>__DEV__</code> <code>ios.webView.inspectable: false</code> <p>The same settings in one object, debugging left on:</p> <pre><code>import { IOSConstants, WebView, type WebViewProps } from 'react-native-minimal-webview';

export const rnwDefaults = {
  ios: {
    configuration: { allowsInlineMediaPlayback: false, allowsAirPlayForMediaPlayback: false },
    scrollView: {
      contentInsetAdjustmentBehavior: IOSConstants.ContentInsetAdjustmentBehavior.never,
      automaticallyAdjustsScrollIndicatorInsets: false,
    },
  },
  android: {
    webView: { overScrollMode: 0 }, // 0: View.OVER_SCROLL_ALWAYS
  },
} satisfies Pick&lt;WebViewProps, 'ios' | 'android'&gt;;

export function Browser() {
  return (
    &lt;WebView
      source={{ uri: 'https://example.com' }}
      ios={rnwDefaults.ios}
      android={rnwDefaults.android}
      style={{ flex: 1 }}
    /&gt;
  );
}
</code></pre> <p>To add your own keys, merge each root: <code>ios={{ ...rnwDefaults.ios, scrollView: { ...rnwDefaults.ios.scrollView, bounces: false } }}</code>.</p>
